/// The task transformers' auto-model tables give `class`, when exactly one.
pub fn hf_automap_task_v1(class: &str) -> Option<&'static str> {
    HF_AUTOMAP_TASKS_V1.binary_search_by(|(c, _)| (*c).cmp(class)).ok().map(|i| HF_AUTOMAP_TASKS_V1[i].1)
}

/// The task llama.cpp's converter fixes for a GGUF architecture, when its registered classes name exactly one.
pub fn gguf_converter_task_v1(arch: &str) -> Option<&'static str> {
    GGUF_CONVERTER_TASKS_V1.binary_search_by(|(a, _)| (*a).cmp(arch)).ok().map(|i| GGUF_CONVERTER_TASKS_V1[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_tables_are_sorted_unique_and_read_by_binary_search() {
        for w in HF_AUTOMAP_TASKS_V1.windows(2) {
            assert!(w[0].0 < w[1].0, "{} before {}", w[0].0, w[1].0);
        }
        for w in GGUF_CONVERTER_TASKS_V1.windows(2) {
            assert!(w[0].0 < w[1].0);
        }
        for w in LLAMA_CPP_MODEL_ARCHS_V1.windows(2) {
            assert!(w[0] < w[1]);
        }
        assert_eq!(hf_automap_task_v1("MarianMTModel"), Some("text2text-generation"));
        assert_eq!(hf_automap_task_v1("CLIPModel"), Some("zero-shot-image-classification"));
        // A class transformers lists under two tasks is not a task: never guessed.
        assert_eq!(hf_automap_task_v1("BartForConditionalGeneration"), None);
        assert_eq!(hf_automap_task_v1("CustomResearchModel"), None);
        assert_eq!(gguf_converter_task_v1("glm-dsa"), Some("text-generation"));
        assert_eq!(gguf_converter_task_v1("qwen3"), None, "decided by inference v2's hand table, not here");
        assert!(!LLAMA_CPP_MODEL_ARCHS_V1.contains(&"clip"), "a projector is not a model");
        assert!(LLAMA_CPP_MODEL_ARCHS_V1.contains(&"qwen3tts"));
    }
}
